  "x1.finish": { en: "Finish setup", hi: "\u0938\u0947\u091F\u0905\u092A \u092A\u0942\u0930\u093E \u0915\u0930\u0947\u0902", or: "\u0B38\u0B47\u0B1F\u0B05\u0B2A\u0B4D \u0B38\u0B2E\u0B3E\u0B2A\u0B4D\u0B24 \u0B15\u0B30\u0B28\u0B4D\u0B24\u0B41" },
