  "p1.changeToday": { en: "Change today", hi: "\u0906\u091C \u0915\u093E \u092C\u0926\u0932\u093E\u0935", or: "\u0B06\u0B1C\u0B3F\u0B30 \u0B2A\u0B30\u0B3F\u0B2C\u0B30\u0B4D\u0B24\u0B4D\u0B24\u0B28" },
