  "s1.shop": { en: "Your shop", hi: "\u0906\u092A\u0915\u0940 \u0926\u0941\u0915\u093E\u0928", or: "\u0B06\u0B2A\u0B23\u0B19\u0B4D\u0B15 \u0B26\u0B4B\u0B15\u0B3E\u0B28" },
