  /* ---- S3 · Language and display --------------------------------------- */
  "s3.title": { en: "Language and screen", hi: "\u092D\u093E\u0937\u093E \u0914\u0930 \u0938\u094D\u0915\u094D\u0930\u0940\u0928", or: "\u0B2D\u0B3E\u0B37\u0B3E \u0B13 \u0B38\u0B4D\u0B15\u0B4D\u0B30\u0B40\u0B28" },
