  "s10.status.free": { en: "You are on Free.", hi: "\u0906\u092A \u092E\u0941\u092B\u093C\u094D\u0924 \u092A\u094D\u0932\u093E\u0928 \u092A\u0930 \u0939\u0948\u0902\u0964", or: "\u0B06\u0B2A\u0B23 \u0B2E\u0B3E\u0B17\u0B23\u0B3E \u0B2A\u0B4D\u0B32\u0B3E\u0B28\u0B30\u0B47 \u0B05\u0B1B\u0B28\u0B4D\u0B24\u0B3F\u0964" },
